      </div>
    `;

    const cardListEl = colEl.querySelector('.card-list');
    column.cards.forEach(card => {
      cardListEl.appendChild(createCardElement(card));
    });

    // Add card event
    const input = colEl.querySelector('.add-card-input');
    const button = colEl.querySelector('.add-card-button');
    const addCardHandler = async () => {
      const text = input.value.trim();
      if (!text) return;

      // Optimistic update: just add it to the end of the list in DOM
      const optimisticCard = { id: 'temp-' + Date.now(), text, column_id: column.id, position: 999999 };
      cardListEl.appendChild(createCardElement(optimisticCard));
      input.value = '';

      try {
        const res = await fetch(`${API_BASE}/cards`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ columnId: column.id, text })
        });
        const cardFromServer = await res.json();
        // The SSE will handle updating the DOM to the canonical state
      } catch (err) {
        console.error('Error adding card:', err);
      }
    };

    button.onclick = addCardHandler;
    input.onkeypress = (e) => { if (e.key === 'Enter') addCardHandler(); };

    boardEl.appendChild(colEl);
  });

  setupDragAndDrop();
}

function createCardElement(card) {
  const el = document.createElement('div');
  el.className = 'card';
  el.draggable = true;
  el.id = card.id;
  el.textContent = card.text;

  el.ondragstart = (e) => {
    e.dataTransfer.setData('text/plain', card.id);
    el.classList.add('dragging');
  };

  el.ondragend = () => {
    el.classList.remove('dragging');
  };

  return el;
}

function setupDragAndDrop() {
  const lists = document.querySelectorAll('.card-list');

  lists.forEach(list => {
    list.ondragover = (e) => {
      e.preventDefault();
      const draggingEl = document.querySelector('.dragging');
      if (!draggingEl) return;

      const afterElement = getDragAfterElement(list, e.clientY);
      if (afterElement == null) {
        list.appendChild(draggingEl);
      } else {
        list.insertBefore(draggingEl, afterElement);
      }
    };

    list.ondrop = async (e) => {
      e.preventDefault();
      const cardId = e.dataTransfer.getData('text/plain');
      const columnId = list.dataset.columnId;

      const children = Array.from(list.children);
      const cardEl = children.find(el => el.id === cardId);
      const index = children.indexOf(cardEl);

      const beforeId = index > 0 ? children[index - 1].id : null;
      const afterId = index < children.length - 1 ? children[index + 1].id : null;

      try {
        await fetch(`${API_BASE}/cards/${cardId}/move`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ columnId, beforeId, afterId })
        });
      } catch (err) {
        console.error('Error moving card:', err);
        // On error, we should ideally revert the DOM, but SSE will eventually correct it
      }
    };
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll('.card:not(.dragging)')];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      return { offset: offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

function setupSSE() {
  const eventSource = new EventSource(`${API_BASE}/stream`);

  eventSource.addEventListener('card_created', (e) => {
    const card = JSON.parse(e.data);
    const list = document.querySelector(`.card-list[data-column-id="${card.column_id}"]`);
    if (list) {
      // Avoid duplicates if optimistic update already added it
      const existing = document.getElementById(card.id);
      if (existing) {
        existing.id = card.id; // just in case it was temp
        existing.textContent = card.text;
      } else {
        list.appendChild(createCardElement(card));
      }
    }
  });

  eventSource.addEventListener('card_moved', (e) => {
    const { card, columnId } = JSON.parse(e.data);
    const list = document.querySelector(`.card-list[data-column-id="${columnId}"]`);
    if (list) {
      const cardEl = document.getElementById(card.id);
