  });

  eventSource.addEventListener('column_updated', (e) => {
    const { columnId, cards } = JSON.parse(e.data);
    const list = document.querySelector(`.card-list[data-column-id="${columnId}"]`);
    if (list) {
      list.innerHTML = '';
