  const eventSource = new EventSource(`${API_BASE}/stream`);

  eventSource.addEventListener('card_created', (e) => {
    const card = JSON.parse(e.data);
    const list = document.querySelector(`.card-list[data-column-id="${card.column_id}"]`);
    if (list) {
      // Avoid duplicates if optimistic update already added it
      const existing = document.getElementById(card.id);
      if (existing) {
